css:
/* A derivation step. Inset from the prose margin, with a hairline that
   groups it with the sentence that introduced it, and ASYMMETRIC space
   — tight above, open below — so the gap falls BETWEEN steps rather
   than inside one.

   The only label is the markdown's own `…(i)`. A derived count in the
   gutter was a second numbering system on the same equation, and the
   prose cites the author's, not ours. */
.dm { font-family:'Times New Roman',Times,serif; font-style:italic; font-size:19.5px;
      text-align:center; margin:3px 0 11px; padding:1px 0 1px 14px;
      border-left:2px solid #e4dfd2; line-height:1.5; overflow-x:auto;
      font-variant-numeric:lining-nums; }
.acol .dm { padding-left:10px; }
/* The equation label, set apart so it reads as a reference the prose
   can cite rather than as part of the maths. */
.dm .k { float:right; font-style:normal; font-size:15.5px;
         font-weight:700; color:#3a5a8c;
         background:#eef3fb; border-radius:4px;
         padding:1px 7px; margin-left:8px; white-space:nowrap; }

/* The arrow is tucked and shrunk rather than the line being opened.
   Raising `line-height` to 1.75 cleared the collision and spread every
   equation so far apart that the page lost its rhythm. */
.dm .vec::after { top:-0.52em; font-size:0.5em; }

/* A `=` chain: left-hand side, sign, expression — three columns, so the
   signs line up down the page by construction.

   The left-hand side shares the FIRST row. Given a row of its own it
   sat alone above the chain with a gap beneath it and read as a stray
   symbol; every row after the first leaves that cell empty. */
.dm-chain { display:grid; grid-template-columns:auto auto 1fr;
            column-gap:6px; row-gap:1px; text-align:left;
            justify-content:start; margin:3px 0 11px; }
.dm-chain .chl { text-align:right; white-space:nowrap; }
.dm-chain .chop { text-align:center; white-space:nowrap; }
.dm-chain .chex { text-align:left; }
